//势魏延忠傲失败
lib.element.player.removeZhuangshiUI = function() {
    var player = this;   
    var powerFillNode = document.querySelector('.shiweiyanPowerFill');
    if (powerFillNode && !player.storage.shiweiyanJdt_anim) {
        Tts.SS_ShiWeiyanSkillJdt.action = 'play';
        dcdAnim.loadSpine(Tts.SS_ShiWeiyanSkillJdt.name, "skel", () => {
            player.storage.shiweiyanJdt_anim = dcdAnim.playSpine(Tts.SS_ShiWeiyanSkillJdt, {
                scale: 1,
                x: [0, 0.5],
                y: [0, 0.5],
                parent: powerFillNode
            });
        });
    }
    if (ui._shiweiyanPower) {
        ui._shiweiyanPower.style.opacity = '0';
        ui._shiweiyanPower.style.transition = 'opacity 0.2s';
        setTimeout(() => {
            if (ui._shiweiyanPower) {
                var powerFills = ui._shiweiyanPower.querySelectorAll('.shiweiyanPowerFill');
                for (var i = 0; i < powerFills.length; i++) {
                    var fill = powerFills[i];
                    if (fill.desc && fill.desc.parentNode) {
                        fill.desc.parentNode.removeChild(fill.desc);
                    }
                }
                if (ui._shiweiyanPower.parentNode) {
                    ui._shiweiyanPower.parentNode.removeChild(ui._shiweiyanPower);
                }
                ui._shiweiyanPower = undefined;
            }
            if (game._syncShiweiyanPower) {
                game._syncShiweiyanPower = undefined;
            }
        }, 3000);
    }
    delete player.storage.s_zhuangshi_count;
    delete player.storage.s_zhuangshi_count2;
    player.unmarkSkill('s_zhuangshi');
};

lib.element.player.usekuanggu = function(x) {
var player = this;
    var actionName = 'play' + x;
    dcdAnim.loadSpine(Tts.SS_ShiWeiyanFaDongSkill.name, "skel", function () {
        Tts.SS_ShiWeiyanFaDongSkill.loop = false;
        Tts.SS_ShiWeiyanFaDongSkill.action = actionName;
        player.storage.s_zhongao_fail = dcdAnim.playSpine(Tts.SS_ShiWeiyanFaDongSkill, { 
            scale: 0.75, 
            x: [0, 0.58], 
            y: [0, 0.52], 
            parent: player 
        });
    });
};
lib.element.player.redeye = function(command, x) {
var player = this;
    var storageKey, spineName, actionName;
    
    if (x == 1) {
        storageKey = 's_zhongao_kuanggu';
        spineName = Tts.SS_SWY_zhuangtai1hongyan.name;
        actionName = 'play';
    } else if (x == 2) {
        storageKey = 's_zhongao_success';
        spineName = Tts.SS_SWY_zhuangtai2hongyan.name;
        actionName = 'play';
    } else if (x == 3) {
        storageKey = 's_zhongao_fail';
        spineName = Tts.SS_SWY_zhuangtai3hongyan.name;
        actionName = 'play';
    }
    
    if (command == 'on') {
        if (player.storage[storageKey] == undefined) {
            dcdAnim.loadSpine(spineName, "skel", function () {
                if(x == 1){
                    Tts.SS_SWY_zhuangtai1hongyan.loop = true;
                    Tts.SS_SWY_zhuangtai1hongyan.action = actionName;
                    player.storage.s_zhongao_kuanggu = dcdAnim.playSpine(Tts.SS_SWY_zhuangtai1hongyan, { 
                        scale: 0.88, 
                        speed:0.1,
                        x: [0, 0.59], 
                        y: [0, 0.53], 
                        parent: player 
                    });
                }else if(x == 2){
                    Tts.SS_SWY_zhuangtai2hongyan.loop = true;
                    Tts.SS_SWY_zhuangtai2hongyan.action = actionName;
                    player.storage.s_zhongao_success = dcdAnim.playSpine(Tts.SS_SWY_zhuangtai2hongyan, { 
                        scale: 0.8, 
                        x: [0, 0.56], 
                        y: [0, 0.56], 
                        parent: player 
                    });
                }else if(x == 3){
                    Tts.SS_SWY_zhuangtai3hongyan.loop = true;
                    Tts.SS_SWY_zhuangtai3hongyan.action = actionName;
                    player.storage.s_zhongao_fail = dcdAnim.playSpine(Tts.SS_SWY_zhuangtai3hongyan, { 
                        scale: 1, 
                        x: [0, 0.52], 
                        y: [0, 0.52], 
                        parent: player 
                    });
                }
            });
        }
    } else if (command == 'off') {
        if (player.storage[storageKey] != undefined) {
            decadeUI.animation.stopSpine(player.storage[storageKey]);
            player.storage[storageKey] = undefined;
        }
    }
};
