lib.skill._s_zhuangshi_power = {
    trigger: {
        global: "gameStart",
    },
    forced: true,
    popup: false,
    filter: function(event, player) {
        return player == game.me && player.name == 's_weiyan' && !ui._shiweiyanPower;
    },
    content: function() {
        var container = ui.create.div('.shiweiyanPowerContainer', ui.arena);
        ui._shiweiyanPower = container;
        var fills = [
            { key: 's_zhuangshi_count', text: '【壮誓-不能响应】', right: 0 },
            { key: 's_zhuangshi_count2', text: '【壮誓-不计次数】', right: 8 }
        ];
        for (var i = 0; i < fills.length; i++) {
            var item = fills[i];
            var fill = ui.create.div('.shiweiyanPowerFill', container);
            fill.countKey = item.key;
            fill.style.right = item.right + 'px';
            var desc = document.createElement('div');
            desc.classList.add('shiweiyanPowerDesc');
            desc.innerHTML = '<p style="margin: 2%;">' + item.text + '：0次</p>';
            fill.desc = desc;
            document.body.appendChild(desc);
            fill.addEventListener('click', function(e) {
                e.cancelBubble = true;
                e.returnValue = false;
                return false;
            });
            fill.onmouseover = function() {
                this.style.zIndex = '10';
                var count = (game.me && game.me.storage[this.countKey]) || 0;
                this.desc.innerHTML = '<p style="margin: 2%;">' + this.getAttribute('data-text') + '：' + count + '次</p>';
                var rect = this.getBoundingClientRect();
                this.desc.style.top = (rect.top + window.scrollY - this.desc.offsetHeight - 15) + 'px';
                this.desc.style.left = (rect.left + window.scrollX - 160) + 'px';
                this.desc.style.display = 'block';
            };
            fill.onmouseout = function() {
                this.style.zIndex = '6';
                this.desc.style.display = 'none';
            };
            fill.setAttribute('data-text', item.text);
        }
        game._syncShiweiyanPower = function() {
            if (!game.me || !ui._shiweiyanPower) return;
            var powerFills = ui._shiweiyanPower.querySelectorAll('.shiweiyanPowerFill');
            for (var i = 0; i < powerFills.length; i++) {
                var fill = powerFills[i];
                var count = Math.min((game.me.storage[fill.countKey] || 0), 5);
                fill.style.height = (count * 31) + 'px';
            }
        };
        setInterval(function() {
            if (game._syncShiweiyanPower) game._syncShiweiyanPower();
        }, 500);
    },
};
    //搬运了西瓜大佬标记补充扩展的数字按钮美化功能，封装为player.digitbutton(min, max)
    lib.element.player.digitbutton = function(min, max){
        var player = this;
        if(arguments.length === 1){
            max = min;
            min = 1;
        }
        min = Math.max(1, min|0);
        max = Math.max(min, max|0);
        
        var v = min;
        var cls = 'tethys-digit';
        var bg = ui.create.div('.' + cls + '-bg', document.body);
        var m = ui.create.div('.' + cls + '-minus', bg);
        var p = ui.create.div('.' + cls + '-plus', bg);
        var n = ui.create.div('.' + cls + '-num', bg);
        
        var r = function(){
            n.innerHTML = v;
            m.style.filter = (v <= min) ? 'grayscale(100%)' : 'none';
            p.style.filter = (v >= max) ? 'grayscale(100%)' : 'none';
            player._tts = v;
        };
        
        var b = function(x){
            x.style.transform = 'scale(0.7)';
            setTimeout(function(){ x.style.transform = 'scale(1)'; }, 200);
        };
        
        m.listen(function(){ if(v <= min) return; v--; b(m); r(); });
        p.listen(function(){ if(v >= max) return; v++; b(p); r(); });
        r();
        
        player._tts_close = function(){ try{ bg.remove(); }catch(e){} };
        
        return player.chooseBool('请选择一个数字' ).set('ai', function(){
            return true;
        });
    };
    var _loseHp = lib.element.player.loseHp;
    lib.element.player.loseHp = function(num){
        if(num === 'tts'){
            num = this._tts || 0;
            if(this._tts_close){ this._tts_close(); this._tts_close = null; }
        }
        return _loseHp.call(this, num);
    };
    
    var _draw = lib.element.player.draw;
    lib.element.player.draw = function(num, ...args){
        if(num === 'tts'){
            num = this._tts || 0;
            if(this._tts_close){ this._tts_close(); this._tts_close = null; }
        }
        return _draw.call(this, num, ...args);
    };
    
    var _damage = lib.element.player.damage;
