      // 重写 trySkillAudio 函数
      game.trySkillAudio = function(skill, player, directaudio) {
        game.broadcast(game.trySkillAudio, skill, player, directaudio);
        var info = get.info(skill);
        if (!info) return;
        
        if ((!info.direct || directaudio) && lib.config.background_speak &&
          (!lib.skill.global.contains(skill) || lib.skill[skill].forceaudio)) {
          
          var audioname = skill;
          var audioinfo = info.audio;
          var playerId = player ? (player.name || player.name1) : null;
          
          //  audioother 映射优先处理 
          if (info.audioother && playerId && info.audioother[playerId]) {
            var otherConfig = info.audioother[playerId];
            var audioPlayed = false;
            
            // 处理格式: "ext:路径:数量"
            if (typeof otherConfig === 'string' && otherConfig.indexOf('ext:') === 0) {
              var parts = otherConfig.split(':');
              if (parts.length === 3) {
                var extPath = parts[1];
                var audioCount = parts[2];
                
                if (audioCount === 'true') {
                  game.playAudio('..', 'extension', extPath, audioname, function() {
                    tryDefaultAudio();
                  });
                  audioPlayed = true;
                } else {
                  audioCount = parseInt(audioCount);
                  if (audioCount) {
                    var index = Math.ceil(audioCount * Math.random());
                    game.playAudio('..', 'extension', extPath, audioname + index, function() {
                      tryDefaultAudio();
                    });
                    audioPlayed = true;
                  }
                }
              }
            }
            else if (typeof otherConfig === 'object' && otherConfig.path) {
              var path = otherConfig.path;
              var count = otherConfig.count || 1;
              
              if (path.indexOf('ext:') === 0) {
                var parts = path.split(':');
                if (parts.length >= 2) {
                  var extPath = parts[1];
                  var index = Math.ceil(count * Math.random());
                  game.playAudio('..', 'extension', extPath, audioname + index, function() {
                    tryDefaultAudio();
                  });
                  audioPlayed = true;
                }
              }
            }
            
            if (audioPlayed) return;
          }
          
          var tryDefaultAudio = function() {
            var defaultAudioInfo = info.audio;
            var defaultAudioName = audioname;
            
            if (info.audioname2 && info.audioname2[playerId]) {
              defaultAudioName = info.audioname2[playerId];
              var linkedInfo = lib.skill[defaultAudioName];
              if (linkedInfo && linkedInfo.audio) {
                defaultAudioInfo = linkedInfo.audio;
              }
            }
            
            if (typeof defaultAudioInfo === 'string' && lib.skill[defaultAudioInfo]) {
              defaultAudioName = defaultAudioInfo;
              defaultAudioInfo = lib.skill[defaultAudioName].audio;
            }
            
            if (typeof defaultAudioInfo === 'string' && defaultAudioInfo.indexOf('ext:') === 0) {
              var parts = defaultAudioInfo.split(':');
              if (parts.length === 3) {
                var extPath = parts[1];
                var audioCount = parts[2];
                
                if (audioCount === 'true') {
                  game.playAudio('..', 'extension', extPath, defaultAudioName);
                } else {
                  audioCount = parseInt(audioCount);
                  if (audioCount) {
                    game.playAudio('..', 'extension', extPath, defaultAudioName + Math.ceil(audioCount * Math.random()));
                  }
                }
                return;
              }
            }
            else if (Array.isArray(defaultAudioInfo)) {
              defaultAudioName = defaultAudioInfo[0];
              defaultAudioInfo = defaultAudioInfo[1];
            }
            
            if (Array.isArray(info.audioname) && player) {
              if (info.audioname.contains(player.name)) {
                defaultAudioName += '_' + player.name;
              }
              else if (player.name1 && info.audioname.contains(player.name1)) {
                defaultAudioName += '_' + player.name1;
              }
              else if (player.name2 && info.audioname.contains(player.name2)) {
                defaultAudioName += '_' + player.name2;
              }
            }
            if (typeof defaultAudioInfo === 'number') {
              game.playAudio('skill', defaultAudioName + Math.ceil(defaultAudioInfo * Math.random()));
            }
            else if (defaultAudioInfo) {
              game.playAudio('skill', defaultAudioName);
            }
            else if (info.audio !== false) {
              game.playSkillAudio(defaultAudioName);
            }
          };
          tryDefaultAudio();
        }
      };
