lib.skill._replace_name_prefix = {
    trigger: {
        global: 'gameStart'
    },
    forced: true,
    popup: false,
    charlotte: true,
    forceLoad: true,
    forceDie: true,
    firstDo: true,
    priority: 100,
    content: function() {
        var prefixes = ['谋','势'/*,'友','神','星','界','魔'*/];
        game.players.concat(game.dead).forEach(current => {
            var name1 = current.name1;
            var name2 = current.name2;
            if (name1 && lib.translate[name1]) {
                var translatedName = lib.translate[name1];
                prefixes.forEach(prefix => {
                    if (translatedName.startsWith(prefix) && !translatedName.includes('·')) {
                        lib.translate[name1] = prefix + '·' + translatedName.substring(1);
                    }
                });
            }
            if (name2 && lib.translate[name2]) {
                var translatedName = lib.translate[name2];
                prefixes.forEach(prefix => {
                    if (translatedName.startsWith(prefix) && !translatedName.includes('·')) {
                        lib.translate[name2] = prefix + '·' + translatedName.substring(1);
                    }
                });
            }
            if (current.node && current.node.name) {
                current.node.name.innerHTML = get.verticalStr(get.rawName(current.name), true);
            }
            if (current.node && current.node.name2) {
                current.node.name2.innerHTML = get.verticalStr(get.rawName(current.name2), true);
            }
        });
    }
};
