"hy_fentao":{
    audio: "ext:手杀武将/apk/势魏延/audio/hy_zhouyu:2",
    audioother: {
        "hy_zhouyu": "ext:手杀武将/apk/势魏延/audio/hy_zhouyu:2",
        "hy_zhouyu2": "ext:手杀武将/apk/势魏延/audio/hy_zhouyu2:4",
        "hy_zhouyu3": "ext:手杀武将/apk/势魏延/audio/hy_zhouyu2:4"
    },
    trigger:{global:"damageBegin3"},
    filter:function(e,p){return e.nature==='fire'&&e.player!==p&&e.player.isLinked();},
    forced:true,popup:false,logTarget:"player",
    content:function(){
        "step 0"
        event.t=trigger.player;var ch=player.storage.hy_xiongzi_choice;
        var sp=ch===2?Tts.SS_jn_szyskillblue:Tts.SS_jn_szyskillred;
        dcdAnim.loadSpine(sp.name,"skel",function(){sp.loop=false;sp.action='play3';dcdAnim.playSpine(sp,{scale:0.9,parent:player,x:[0,0.5],y:[0,0.5]});});
        var u=player.storage.hy_xiongzi,chs=[];
        if(!u||ch!==2) chs.push("选项一");
        if(!u||ch!==1) chs.push("选项二");
        event.t.chooseControl(chs).set('prompt','焚涛：传导伤害+1 或 弃置一半牌并进入连环').set('ai',function(){
            if(_status.event.controls.length===1) return 0;
            var t=_status.event.getParent().t;
            if(t.countCards('he')<=2) return 1;
            if(t.hp<=1) return 1;
            if(get.attitude(t,_status.event.player)<0) return 0;
            return 1;
        });
        "step 1"
        if(result.control==="选项一"){trigger.num++;}
        else{var c=Math.ceil(event.t.countCards('he')/2);if(c>0) event.t.chooseToDiscard('he',c,true).set("prompt","弃置"+c+"张牌");event.t.storage.hy_fentao_link=true;}
    },
    group:"hy_fentao_link",
    subSkill:{link:{trigger:{player:"damageAfter"},filter:function(e,p){return p.storage.hy_fentao_link;},forced:true,content:function(){player.link(true);delete player.storage.hy_fentao_link;},sub:true,parentskill:"hy_fentao"}},
},
